<?php
namespace Dth\Crm\Services; final class LeadFormAnswerSnapshotService {public function build(array $answers):array{return array_values(array_map(function($a,$k){if(is_array($a)&&array_key_exists('value',$a))return $a+['key'=>$a['key']??$k];return ['key'=>(string)$k,'label'=>(string)$k,'value'=>$a,'display_value'=>$this->displayValue($a,[])];},$answers,array_keys($answers)));}public function displayValue(mixed $value,mixed $options):string{if(is_bool($value))return $value?'Có':'Không';if(is_array($value))return implode(', ',array_map('strval',$value));return is_scalar($value)?(string)$value:'';}}
